/**
 * Builds src/core/agent/spelling-allowlist.ts: every real English word (from a
 * system word list) that is within typo distance of a domain word. Those words
 * are never "corrected", so typo repair only touches non-words like "thrusday".
 *
 *   npm run build:spelling -w server                      # uses /usr/share/dict/words
 *   npm run build:spelling -w server -- /path/to/words.txt
 *
 * The generated file is committed, so the app never needs the system word list.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { DOMAIN_VOCAB, editDistance, maxEdits } from '../src/core/agent/spelling.js';

const source = process.argv[2] ?? '/usr/share/dict/words';
const words = new Set(
  readFileSync(source, 'utf8')
    .split(/\r?\n/)
    .map((w) => w.trim().toLowerCase())
    .filter((w) => /^[a-z]{4,}$/.test(w)),
);
const vocab = new Set<string>(DOMAIN_VOCAB);
const collisions: string[] = [];
for (const w of words) {
  if (vocab.has(w)) continue;
  const max = maxEdits(w.length);
  if (DOMAIN_VOCAB.some((v) => editDistance(w, v, max) <= max)) collisions.push(w);
}
collisions.sort();
const out = new URL('../src/core/agent/spelling-allowlist.ts', import.meta.url).pathname;
const body = collisions.map((w) => `'${w}'`).join(', ');
writeFileSync(
  out,
  `/** Generated by \`npm run build:spelling -w server\` from ${source} (do not edit by hand). */\n` +
    `// Real English words within typo distance of a domain word: never auto-corrected.\n` +
    `export const SPELLING_ALLOWLIST: readonly string[] = [${body}];\n`,
);
console.log(`${words.size} dictionary words scanned; ${collisions.length} near-collisions written to ${out}`);
